"""Tests for tasks_api.queries — TaskQuery validation, apply_query filtering/sort/pagination."""

from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskQuery, TaskQueryError, apply_query

from .conftest import make_task

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("bad_sort", ["id", "unknown", ""])
    def test_invalid_sort_raises(self, bad_sort):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort=bad_sort)

    @pytest.mark.parametrize("bad_limit", [0, -1, 101, "abc"])
    def test_invalid_limit_raises(self, bad_limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=bad_limit)

    @pytest.mark.parametrize("bad_offset", [-1, -100])
    def test_invalid_offset_raises(self, bad_offset):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=bad_offset)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  HELLO  ")
        assert q.tag == "hello"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="!!!")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"


class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        return [
            make_task(id=1, title="Buy milk", status=TaskStatus.PENDING, tags=[Tag("shopping")]),
            make_task(id=2, title="Write code", status=TaskStatus.DONE, tags=[Tag("work")]),
            make_task(
                id=3,
                title="Pay bills",
                status=TaskStatus.PENDING,
                due_at=datetime(2025, 1, 1, tzinfo=timezone.utc),
                tags=[Tag("finance")],
            ),
        ]

    def test_no_filters_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 3

    def test_filter_by_status(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="milk"), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_search_is_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="WRITE"), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 3

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        assert page.total == 2
        assert all(t.id != 3 for t in page.items)


class TestApplyQuerySorting:
    @pytest.fixture
    def tasks(self):
        return [
            make_task(id=1, title="Banana", priority=TaskPriority.LOW,
                      created_at=datetime(2025, 3, 1, tzinfo=timezone.utc)),
            make_task(id=2, title="Apple", priority=TaskPriority.HIGH,
                      created_at=datetime(2025, 1, 1, tzinfo=timezone.utc)),
            make_task(id=3, title="Cherry", priority=TaskPriority.MEDIUM,
                      created_at=datetime(2025, 2, 1, tzinfo=timezone.utc)),
        ]

    def test_sort_by_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]

    def test_sort_by_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), NOW)
        assert [t.id for t in page.items] == [1, 3, 2]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        # HIGH=0, MEDIUM=1, LOW=2
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH,
            TaskPriority.MEDIUM,
            TaskPriority.LOW,
        ]

    def test_sort_by_due_at_none_last(self):
        tasks = [
            make_task(id=1, title="no due", due_at=None),
            make_task(id=2, title="early", due_at=datetime(2025, 1, 1, tzinfo=timezone.utc)),
            make_task(id=3, title="late", due_at=datetime(2025, 12, 1, tzinfo=timezone.utc)),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]


class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [make_task(id=i, title=f"Task {i}") for i in range(1, 11)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=8), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 10
        assert page.has_more is False

    def test_page_properties(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=3), NOW)
        assert page.limit == 5
        assert page.offset == 3

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags

from .conftest import make_task


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3

    def test_add_and_get(self, repo):
        task = make_task(id=1)
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        task = make_task(id=1)
        repo.add(task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(task)

    def test_list_returns_all(self, repo):
        repo.add(make_task(id=1, title="A"))
        repo.add(make_task(id=2, title="B"))
        items = list(repo.list())
        assert len(items) == 2

    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_update(self, repo):
        task = make_task(id=1, title="Original")
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("foo"), Tag("FOO"), Tag("bar")])
        assert [t.name for t in result] == ["foo", "bar"]

    def test_accepts_strings(self):
        result = normalize_tags(["Hello", "World"])
        assert [t.name for t in result] == ["hello", "world"]

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("aaa"), "AAA", "bbb"])
        assert [t.name for t in result] == ["aaa", "bbb"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["c", "a", "b", "A"])
        assert [t.name for t in result] == ["c", "a", "b"]

